import { IDigitalRideMediaService } from "@/core/services";
import { TodayHelper, multipleClassNames } from "@/core/helpers";
import structure from "@/core/styling/structure.module.less";
import styles from "./digital-ride-media-qr-code-connect-block.module.less";
import { SaveToAlbum } from "../elements";
import { useMutation, useQuery } from "@tanstack/react-query";
import { useEffect, useState } from "react";
import { AnimatedFerrisWheel } from "@/core/components/primitives/animated-ferris-wheel/animated-ferris-wheel";
import { useTranslation } from "react-i18next";
import Banner from "@/core/components/primitives/banner/banner";

type Props = {
  qrCodeAccountId: string;
  service: IDigitalRideMediaService;
  navigateToAlbum: (albumId: string) => void;
};

const DigitalRideMediaQrCodeConnectBlock = ({ qrCodeAccountId, service, navigateToAlbum }: Props) => {
  const { t } = useTranslation();

  const {
    data: qrCodeAccountMedia,
    isLoading: isLoadingQrCodeMedia,
    error: errorLoadingMediaOnQrCodeAccount,
    // eslint-disable-next-line @tanstack/query/exhaustive-deps
  } = useQuery({
    queryKey: ["qr-code-media", qrCodeAccountId],
    queryFn: () => service.getMediaOnQrCodeAccount(qrCodeAccountId),
  });

  const [isSavingToExistingAlbumId, setIsSavingToExistingAlbumId] = useState<string>();
  const [isErrorOnSaveToExistingAlbumId, setIsErrorOnSaveToExistingAlbumId] = useState<string>();
  const { mutate: connectToAlbum } = useMutation({
    mutationFn: (albumId: string) => service.connectQrCodeToAlbum(qrCodeAccountId, albumId),
    onMutate: (albumId) => {
      setIsSavingToExistingAlbumId(albumId);
    },
    onSuccess: (_data, albumId) => {
      navigateToAlbum(albumId);
    },
    onError: (_error, albumId) => {
      setIsSavingToExistingAlbumId(undefined);
      setIsErrorOnSaveToExistingAlbumId(albumId);
    },
  });

  const [newlyCreatedAlbumId, setNewlyCreatedAlbumId] = useState<string>();

  const {
    mutate: saveAlbum,
    isPending: isLoadingCreateAlbum,
    error: createNewAlbumError,
  } = useMutation({
    mutationFn: () => service.createNewAlbum(),
    onSuccess: (data) => {
      if (!data.item?.albumId) {
        console.error("No albumId returned from createNewAlbum");
        return;
      }
      setNewlyCreatedAlbumId(data.item.albumId);
    },
  });

  useEffect(() => {
    if (newlyCreatedAlbumId) {
      connectToAlbum(newlyCreatedAlbumId);
    }
  }, [newlyCreatedAlbumId, connectToAlbum]);

  const numberOfMediaOnQrCodeAccount = qrCodeAccountMedia?.media?.items?.length ?? 0;
  const photoDateString = qrCodeAccountMedia?.media?.items?.map((media) => media.dateString).find((date) => !!date);

  return (
    <section className={multipleClassNames(styles.outerWrapper, structure.block, structure.blockMaxWidthM)}>
      {isLoadingQrCodeMedia && <AnimatedFerrisWheel />}
      {errorLoadingMediaOnQrCodeAccount && (
        <Banner
          type="critical"
          heading={t("somethingWentWrong")}
          paragraph={t("rideMediaConnectQrCodeErrorBannerParagraph")}
        />
      )}
      {qrCodeAccountMedia && (
        <div className={styles.innerWrapper}>
          <h1 data-testid="digital-ride-media-qr-code-connect-heading">
            {t("rideMediaConnectQrCodeHeading", { count: numberOfMediaOnQrCodeAccount })}
          </h1>
          <SaveToAlbum
            wrappingElement="div"
            service={service}
            isVisible
            visitDate={photoDateString ?? TodayHelper.getNow().toISOString()}
            createNewAlbum={() => {
              saveAlbum();
            }}
            createNewAlbumError={createNewAlbumError}
            addToExistingAlbum={(albumId) => {
              connectToAlbum(albumId);
            }}
            isLoadingCreateAlbum={isLoadingCreateAlbum}
            isLoadingSaveToExistingAlbumId={isSavingToExistingAlbumId}
            isErrorOnSaveToExistingAlbumId={isErrorOnSaveToExistingAlbumId}
            qrCodeAccountMediaNumber={numberOfMediaOnQrCodeAccount}
          />
        </div>
      )}
    </section>
  );
};

export default DigitalRideMediaQrCodeConnectBlock;
